    private fun encodeRationalNumberType(w: BitWriter, msg: RationalNumberType) {
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        w.writeBits((msg.exponent.toLong() - -128L).toUInt(), 8)
