        r.readBits(1)   // child EE
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _value = ExiPrimitives.readSignedInteger(r).toShort()
        r.readBits(1)   // child EE
        r.readBits(1)   // element EE
        return RationalNumberType(_exponent, _value)
