                        st290 = 1
                    } else if (msg.overFrequencyDroop != null) {
                        w.writeBits(1u, 3)   // OverFrequencyDroop
                        encodeFrequencyDroopSettingsType(w, msg.overFrequencyDroop!!)
                        st290 = 2
                    } else if (msg.underFrequencyDroop != null) {
                        w.writeBits(2u, 3)   // UnderFrequencyDroop
                        encodeFrequencyDroopSettingsType(w, msg.underFrequencyDroop!!)
                        st290 = 3
                    } else {
                        w.writeBits(3u, 3)   // element EE
                        done290 = true
                    }
                }
