                    if (msg.underFrequencyDroop != null) {
                        w.writeBits(0u, 2)   // UnderFrequencyDroop
                        encodeFrequencyDroopSettingsType(w, msg.underFrequencyDroop!!)
                        st290 = 3
                    } else {
                        w.writeBits(1u, 2)   // element EE
                        done290 = true
                    }
